CodeAssembler& CodeAssemblerFns8::vpsravd(AsmRegisterXmm op0, AsmRegisterXmm op1, AsmMemoryOperand op2) {
	Code code;
	if (op2.is_broadcast()) {
		code = Code::EVEX_Vpsravd_xmm_k1z_xmm_xmmm128b32;
	} else if (instruction_prefer_vex()) {
		code = Code::VEX_Vpsravd_xmm_xmm_xmmm128;
	} else {
		code = Code::EVEX_Vpsravd_xmm_k1z_xmm_xmmm128b32;
	}
	return add_instr_with_state(Instruction::with3(code, op0.register_(), op1.register_(), to_memory_operand(op2)), op0.state().merge(op2.state()));
}

CodeAssembler& CodeAssemblerFns8::vpsravd(AsmRegisterYmm op0, AsmRegisterYmm op1, AsmMemoryOperand op2) {
	Code code;
	if (op2.is_broadcast()) {
		code = Code::EVEX_Vpsravd_ymm_k1z_ymm_ymmm256b32;
	} else if (instruction_prefer_vex()) {
		code = Code::VEX_Vpsravd_ymm_ymm_ymmm256;
	} else {
		code = Code::EVEX_Vpsravd_ymm_k1z_ymm_ymmm256b32;
	}
	return add_instr_with_state(Instruction::with3(code, op0.register_(), op1.register_(), to_memory_operand(op2)), op0.state().merge(op2.state()));
}

